package org.brightstats.data;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.*;
public final class WorkspaceChecks {
    private static int checks;
    private static void require(boolean condition,String label){checks++;if(!condition)throw new AssertionError(label);}
    private interface Action{void run()throws Exception;}
    private static void rejects(Action action)throws Exception{try{action.run();throw new AssertionError("Invalid workspace operation accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);Path root=output.resolve("run-"+UUID.randomUUID());var store=WorkspaceStore.create(root);require(store.manifest().projects().isEmpty(),"Empty workspace");JsonObject document=WorkspaceStore.emptyProject();document.add("columnNames",new Gson().toJsonTree(List.of("X","Y")));document.add("observations",new Gson().toJsonTree(new double[][]{{1,2},{2,3},{3,5}}));var model=DiagramTemplates.regression(List.of("X","Y"),1,new int[]{0},false);var node=model.node(model.root());var properties=node.properties();properties.add("upper",JsonNull.INSTANCE);model=model.with(new TypedDiagram.Node(node.id(),node.type(),node.label(),node.x(),node.y(),properties));var models=new JsonObject();models.add("REGRESSION",model.json());document.add("typedModels",models);document.add("modelLibrary",new ModelLibrary().add("Origin model",model).json());var first=store.add("Primary",document);require(store.read(first.id()).equals(document),"Dataset/models/nulls preserved");byte[] before=Files.readAllBytes(store.path(first.id()));var second=store.duplicate(first.id(),"Alternative");require(!first.id().equals(second.id())&&store.read(second.id()).equals(document),"Independent project files");store.rename(first.id(),"Renamed primary");store.activate(first.id());var reopened=WorkspaceStore.open(root);require(reopened.manifest().active().equals(first.id())&&reopened.project(first.id()).name().equals("Renamed primary"),"Manifest round-trip");JsonObject modified=document.deepCopy();modified.getAsJsonArray("observations").get(0).getAsJsonArray().set(1,new JsonPrimitive(9.));store.save(first.id(),modified);require(store.read(first.id()).equals(modified),"Atomic current save");try(var files=Files.list(root.resolve("history").resolve(first.id()))){var backups=files.toList();require(backups.size()==1&&Arrays.equals(Files.readAllBytes(backups.getFirst()),before),"Byte-identical prior version retained");}require(store.read(second.id()).equals(document),"Other project unchanged");rejects(()->store.rename(first.id(),"alternative"));rejects(()->new WorkspaceStore.Project("../outside","Bad",first.createdUtc(),first.modifiedUtc()));rejects(()->new WorkspaceStore.Manifest("bright-stats-workspace",2,List.of(),""));var bad=document.deepCopy();bad.getAsJsonArray("observations").get(0).getAsJsonArray().set(0,JsonNull.INSTANCE);rejects(()->store.save(first.id(),bad));require(store.read(first.id()).equals(modified),"Invalid save leaves current file intact");store.remove(second.id());require(Files.isRegularFile(root.resolve("projects").resolve(second.id()+".json")),"Removing catalog entry retains project file");var blank=store.add("Empty project",WorkspaceStore.emptyProject());require(store.read(blank.id()).getAsJsonArray("observations").isEmpty(),"Empty project can precede data import");try(var files=Files.walk(root)){require(files.noneMatch(path->path.getFileName().toString().endsWith(".tmp")),"No temporary save files remain");}JsonObject evidence=new JsonObject();evidence.addProperty("checks",checks);evidence.addProperty("workspace",root.toAbsolutePath().toString());evidence.addProperty("projects",store.manifest().projects().size());Files.writeString(output.resolve("core.json"),new GsonBuilder().setPrettyPrinting().create().toJson(evidence));System.out.println(new Gson().toJson(evidence));}
}
